fn splitlines(a: Vec<String>, keepends: bool) -> Vec<Vec<String>> {
    let mut result = Vec::with_capacity(a.len());
    
    for s in a {
        let lines: Vec<String> = if keepends {
            // Split keeping line endings
            s.split_inclusive('\n')
                .map(|line| line.to_string())
                .collect()
        } else {
            // Split without line endings
            s.lines()
                .map(|line| line.to_string())
                .collect()
        };
        
        // Ensure non-empty inner vector
        if lines.is_empty() {
            // If the string was empty or had no lines, include an empty string
            result.push(vec![String::new()]);
        } else {
            result.push(lines);
        }
    }
    
    result
}